#!/usr/bin/env python3
"""Publish the locally tested GEZ-KiNO integration without experimental proxy code."""
import ast,base64,json,zlib,zipfile,xml.etree.ElementTree as ET
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DIR=ROOT/'zips/plugin.video.xship'
NEW='2026.10.20.162'
CHANGES=json.loads(zlib.decompress(base64.b64decode('')))
with zipfile.ZipFile(DIR/'plugin.video.xship-2026.10.13.158.zip') as zi:
    entries={i.filename:zi.read(i) for i in zi.infolist() if not i.is_dir()}
for path,text in CHANGES.items():
    if path.endswith('.py'): ast.parse(text)
    if path.endswith('.xml'): ET.fromstring(text)
    entries[path]=text.encode('utf-8')
assert not any('proxytest' in p or 'vendor_pysocks' in p for p in entries)
assert b'proxytest' not in entries['plugin.video.xship/resources/lib/gezkino.py']
settings=ET.fromstring(entries['plugin.video.xship/resources/settings.xml'])
assert next(s for s in settings.iter('setting') if s.get('id')=='voe.stream_preference').get('default')=='1'
assert ET.fromstring(entries['plugin.video.xship/addon.xml']).get('version')==NEW
assert ("_XSHIP_CHANGELOG_BUILD = '"+NEW+"'").encode() in entries['plugin.video.xship/service.py']
output=DIR/('plugin.video.xship-'+NEW+'.zip')
with zipfile.ZipFile(output,'w',zipfile.ZIP_DEFLATED) as zo:
    for name,data in entries.items():zo.writestr(name,data)
with zipfile.ZipFile(output) as zo:assert zo.testzip() is None
(DIR/'changelog.txt').write_bytes(entries['plugin.video.xship/changelog.txt'])
print('Built GEZ-KiNO release',NEW)
